const ownerEarnings = `-- name: OwnerEarnings :one
SELECT
  COALESCE(sum(net_payable_paise) FILTER (WHERE status = 'paid'), 0)::bigint AS paid_out_paise,
  COALESCE(sum(net_payable_paise) FILTER (WHERE status IN ('pending', 'eligible', 'on_hold')), 0)::bigint AS pending_paise,
  COALESCE(sum(net_payable_paise) FILTER (WHERE status = 'on_hold'), 0)::bigint AS on_hold_paise,
  COALESCE(sum(gross_paise), 0)::bigint AS gross_paise,
  COALESCE(sum(commission_paise + gst_on_commission_paise), 0)::bigint AS commission_paise,
  COALESCE(sum(tcs_paise + tds_paise), 0)::bigint AS withheld_paise,
  count(*) FILTER (WHERE status IN ('pending', 'eligible', 'on_hold'))::int AS pending_count
FROM settlements WHERE owner_org_id = $1
`

type OwnerEarningsRow struct {
	PaidOutPaise    int64 `json:"paid_out_paise"`
	PendingPaise    int64 `json:"pending_paise"`
	OnHoldPaise     int64 `json:"on_hold_paise"`
	GrossPaise      int64 `json:"gross_paise"`
	CommissionPaise int64 `json:"commission_paise"`
	WithheldPaise   int64 `json:"withheld_paise"`
	PendingCount    int32 `json:"pending_count"`
}

func (q *Queries) OwnerEarnings(ctx context.Context, ownerOrgID uuid.UUID) (OwnerEarningsRow, error) {
	row := q.db.QueryRow(ctx, ownerEarnings, ownerOrgID)
	var i OwnerEarningsRow
	err := row.Scan(
		&i.PaidOutPaise,
		&i.PendingPaise,
		&i.OnHoldPaise,
		&i.GrossPaise,
		&i.CommissionPaise,
		&i.WithheldPaise,
		&i.PendingCount,
	)
	return i, err
}

