const transferSources = `-- name: TransferSources :many
SELECT p.id, p.gateway_payment_id, p.purpose::text AS purpose,
       (p.amount_paise
        - COALESCE((SELECT sum(r.amount_paise) FROM refunds r WHERE r.payment_id = p.id AND r.status <> 'failed'), 0)
        - COALESCE((SELECT sum(t.amount_paise) FROM payout_transfers t WHERE t.payment_id = p.id AND t.status NOT IN ('failed', 'reversed')), 0))::bigint AS available_paise,
       EXISTS (SELECT 1 FROM refunds r WHERE r.payment_id = p.id AND r.status <> 'failed') AS has_refunds
FROM payments p
WHERE p.booking_id = $1 AND p.status IN ('captured', 'partially_refunded')
ORDER BY (p.purpose = 'deposit'), p.created_at
`

type TransferSourcesRow struct {
	ID               uuid.UUID `json:"id"`
	GatewayPaymentID *string   `json:"gateway_payment_id"`
	Purpose          string    `json:"purpose"`
	AvailablePaise   int64     `json:"available_paise"`
	HasRefunds       bool      `json:"has_refunds"`
}

// Captured payments of a booking with what can still be transferred.
func (q *Queries) TransferSources(ctx context.Context, bookingID uuid.UUID) ([]TransferSourcesRow, error) {
	rows, err := q.db.Query(ctx, transferSources, bookingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TransferSourcesRow{}
	for rows.Next() {
		var i TransferSourcesRow
		if err := rows.Scan(
			&i.ID,
			&i.GatewayPaymentID,
			&i.Purpose,
			&i.AvailablePaise,
			&i.HasRefunds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

